package fraymus.workspace;

import fraymus.geometry.ReferenceMap;
import fraymus.geometry.TopologyMap;
import org.json.*;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.security.MessageDigest;

/** Original image bytes, learned rules and explicit SI-unit compilation; no image semantics guessed. */
final class MapDefinition {
    static final String SCOPE="Declared-scale3D rigid-body scene from an explicit2D grid/layer. Blocked tiles are solid barriers, not inferred materials or fluid simulation. Original higher-dimensional data remain separate.";
    static final String PROCEDURE="map-world-v1",VERSION="reference-grid-v1";
    static String sha(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}
    static String color(int rgb){return String.format(Locale.ROOT,"#%06x",rgb&0xffffff);}
    static JSONObject image(JSONObject input){return decode(input,false);}
    static JSONObject inspect(JSONObject input){return decode(input,true);}
    private static JSONObject decode(JSONObject input,boolean inspect){
        SpatialScene.keys(input,"pngBase64","tilePixels","walkableColors","title");String encoded=input.getString("pngBase64");if(encoded.length()>360000)throw new IllegalArgumentException("PNG exceeds256KiB");byte[] bytes=Base64.getDecoder().decode(encoded);if(bytes.length>262144)throw new IllegalArgumentException("PNG exceeds256KiB");int tile=Procedural.integer(input,"tilePixels",1,1,16);BufferedImage image;
        try(var stream=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(stream);if(!readers.hasNext())throw new IllegalArgumentException("Choose a PNG tile/palette map");var reader=readers.next();try{if(!reader.getFormatName().equalsIgnoreCase("png"))throw new IllegalArgumentException("PNG required");reader.setInput(stream);int w=reader.getWidth(0),h=reader.getHeight(0);if(w>256||h>256||w%tile!=0||h%tile!=0||w/tile<3||h/tile<3||w/tile>32||h/tile>32)throw new IllegalArgumentException("Reference needs3..32 tiles/axis, integral tile size and at most256 pixels/axis");image=reader.read(0);}finally{reader.dispose();}}catch(IOException e){throw new IllegalArgumentException("Cannot decode PNG",e);}
        int w=image.getWidth()/tile,h=image.getHeight()/tile;var palette=new ArrayList<Integer>();int[] cells=new int[w*h];
        for(int y=0;y<h;y++)for(int x=0;x<w;x++){var counts=new TreeMap<Integer,Integer>();for(int iy=0;iy<tile;iy++)for(int ix=0;ix<tile;ix++){int rgba=image.getRGB(x*tile+ix,y*tile+iy);if((rgba>>>24)!=255)throw new IllegalArgumentException("Use an opaque reference with explicitly labelled tiles");counts.merge(rgba&0xffffff,1,Integer::sum);}int rgb=counts.entrySet().stream().max(Comparator.<Map.Entry<Integer,Integer>>comparingInt(Map.Entry::getValue).thenComparingInt(e->-e.getKey())).orElseThrow().getKey();if(!palette.contains(rgb))palette.add(rgb);if(palette.size()>8)throw new IllegalArgumentException("More than8 dominant tile colours; supply a labelled palette map, not an unsegmented photograph");cells[y*w+x]=palette.indexOf(rgb);}
        var open=new HashSet<String>();if(inspect){int[] counts=new int[palette.size()];for(int cell:cells)counts[cell]++;int most=0;for(int i=1;i<counts.length;i++)if(counts[i]>counts[most])most=i;open.add(color(palette.get(most)));}for(Object raw:input.optJSONArray("walkableColors",new JSONArray())){if(!(raw instanceof String s)||!s.matches("#[0-9a-fA-F]{6}"))throw new IllegalArgumentException("Walkable colours use #rrggbb");open.add(s.toLowerCase(Locale.ROOT));}var colors=new JSONArray();boolean[] walkable=new boolean[palette.size()];for(int i=0;i<walkable.length;i++){colors.put(color(palette.get(i)));walkable[i]=open.remove(color(palette.get(i)));}if(!open.isEmpty())throw new IllegalArgumentException("A declared floor colour is absent from the reference");var rules=ReferenceMap.learn(w,h,cells,walkable);
        return new JSONObject().put("id",UUID.randomUUID().toString()).put("title",input.optString("title","Imported tile reference")).put("version",1).put("pngBase64",encoded).put("imageSha256",sha(bytes)).put("tilePixels",tile).put("width",w).put("height",h).put("cells",new JSONArray(cells)).put("palette",colors).put("walkable",new JSONArray(walkable)).put("frequencies",new JSONArray(rules.frequency())).put("rules",new JSONArray(rules.allowed())).put("scope","Dominant tile colours and observed directional adjacency. Passability is user-declared; not photographic object recognition or measured physical material inference.");
    }
    static ReferenceMap.Rules rules(JSONObject source){var declared=new JSONArray();for(int i=0;i<source.getJSONArray("palette").length();i++)if(source.getJSONArray("walkable").getBoolean(i))declared.put(source.getJSONArray("palette").getString(i));var decoded=image(new JSONObject().put("pngBase64",source.getString("pngBase64")).put("tilePixels",source.getInt("tilePixels")).put("walkableColors",declared));for(String key:List.of("cells","palette","walkable","frequencies","rules","imageSha256","width","height"))if(!new JSONObject().put("v",decoded.get(key)).similar(new JSONObject().put("v",source.get(key))))throw new IllegalStateException("Original image and retained reference differ: "+key);int[] cells=source.getJSONArray("cells").toList().stream().mapToInt(x->((Number)x).intValue()).toArray();boolean[] open=new boolean[source.getJSONArray("walkable").length()];for(int i=0;i<open.length;i++)open[i]=source.getJSONArray("walkable").getBoolean(i);var r=ReferenceMap.learn(source.getInt("width"),source.getInt("height"),cells,open);if(!new JSONArray(r.allowed()).similar(source.getJSONArray("rules"))||!sha(Base64.getDecoder().decode(source.getString("pngBase64"))).equals(source.getString("imageSha256")))throw new IllegalStateException("Reference image or learned adjacency changed");return r;}
    static JSONObject generated(JSONObject source,JSONObject options){
        SpatialScene.keys(options,"seed","width","height","pins","cellSizeM","friction","constraints");int width=Procedural.integer(options,"width",16,8,24),height=Procedural.integer(options,"height",16,8,24),seed=Procedural.integer(options,"seed",2801,0,1_000_000_000);var pins=new ArrayList<ReferenceMap.Pin>();for(Object raw:options.optJSONArray("pins",new JSONArray())){var p=(JSONObject)raw;SpatialScene.keys(p,"x","y","tile");pins.add(new ReferenceMap.Pin(Procedural.integer(p,"x",-1,0,width-1),Procedural.integer(p,"y",-1,0,height-1),Procedural.integer(p,"tile",-1,0,source.getJSONArray("palette").length()-1)));}var contract=options.has("constraints")?MapTopology.constraints(options.getJSONObject("constraints")):null;var global=contract==null?null:TopologyMap.generate(rules(source),width,height,seed,pins,contract);var r=global==null?ReferenceMap.generate(rules(source),width,height,seed,pins):global.candidate();boolean passed=global==null?r.passed():global.passed();var out=new JSONObject().put("version",VERSION).put("width",width).put("height",height).put("seed",seed).put("cells",new JSONArray(r.cells())).put("palette",source.getJSONArray("palette")).put("walkable",source.getJSONArray("walkable")).put("path",new JSONArray(r.path())).put("pins",new JSONArray(r.pins().stream().map(p->new JSONObject().put("x",p.x()).put("y",p.y()).put("tile",p.tile())).toList())).put("generation",new JSONObject().put("passed",passed).put("reason",global==null?r.reason():global.reason()).put("conflicts",r.conflicts()).put("attempts",global==null?r.attempts():global.trials().size()).put("repairs",global==null?r.repairs():global.totalRepairs())).put("source",new JSONObject().put("kind","reference-image").put("reference",source)).put("options",options);if(global!=null)out.put("version","reference-grid-topology-v1").put("topology",MapTopology.evidence(global,contract));if(passed)compile(out,options);MapTopology.verify(out);return out;
    }
    static JSONObject layer(JSONObject goal,JSONArray requested){
        if(!goal.getString("status").equals("completed")||!goal.getJSONObject("proceduralDefinition").getString("type").equals("dungeon"))throw new IllegalArgumentException("Choose a completed verified dungeon");Procedural.verify(goal);var data=Procedural.data(goal);int dimensions=data.getJSONObject("definition").getInt("dimensions"),side=data.getJSONObject("extra").getInt("side");if(side>24)throw new IllegalArgumentException("Physical map compilation currently supports at most24 cells/axis");if(requested!=null&&requested.length()!=dimensions-2)throw new IllegalArgumentException("Declare exactly one layer for every hidden axis");int variants=requested==null?(int)Math.pow(side,dimensions-2):1;JSONObject best=null;int bestSize=0;
        for(int n=0;n<variants;n++){int[] layers=new int[dimensions-2];for(int k=0,rest=n;k<layers.length;k++,rest/=side){layers[k]=requested==null?rest%side:requested.getInt(k);if(layers[k]<0||layers[k]>=side)throw new IllegalArgumentException("Layer outside original grid");}int[] cells=new int[side*side];for(Object raw:data.getJSONArray("nodes")){var p=(JSONArray)raw;boolean match=true;for(int k=0;k<layers.length;k++)match&=p.getInt(k+2)==layers[k];if(match)cells[p.getInt(1)*side+p.getInt(0)]=1;}var route=longestComponentRoute(cells,side,side);if(route.size()>bestSize){bestSize=route.size();best=new JSONObject().put("version",VERSION).put("width",side).put("height",side).put("seed",data.getJSONObject("definition").getInt("seed")).put("cells",new JSONArray(cells)).put("walkable",new JSONArray(List.of(false,true))).put("palette",new JSONArray(List.of("#203449","#d9efe5"))).put("path",new JSONArray(route)).put("pins",new JSONArray()).put("source",new JSONObject().put("kind","procedural-layer").put("goalId",goal.getString("id")).put("sourceSha256",goal.getString("proceduralSha256")).put("dimensions",dimensions).put("layers",new JSONArray(layers)).put("selection",requested==null?"Enumerated layers; selected the longest verified component route":"Explicit user layers").put("original",data)).put("generation",new JSONObject().put("passed",true).put("reason","Original dungeon layer; no cells carved or flattened across hidden axes").put("conflicts",0).put("attempts",1).put("repairs",0));}}
        if(best==null||bestSize<2)throw new IllegalArgumentException("Selected layer has no connected playable route");compile(best,new JSONObject());return best;
    }
    static List<Integer> longestComponentRoute(int[] cells,int w,int h){List<Integer> best=List.of();var done=new HashSet<Integer>();for(int i=0;i<cells.length;i++)if(cells[i]==1&&!done.contains(i)){var distances=flood(cells,w,h,i);done.addAll(distances.keySet());int far=distances.entrySet().stream().max(Map.Entry.comparingByValue()).orElseThrow().getKey();var second=flood(cells,w,h,far);int end=second.entrySet().stream().max(Map.Entry.comparingByValue()).orElseThrow().getKey();var route=ReferenceMap.path(cells,w,h,new boolean[]{false,true},far,end);if(route.size()>best.size())best=route;}return best;}
    static Map<Integer,Integer> flood(int[] cells,int w,int h,int start){var seen=new LinkedHashMap<Integer,Integer>();var q=new ArrayDeque<Integer>();q.add(start);seen.put(start,0);while(!q.isEmpty()){int id=q.remove();for(int n:new int[]{id-1,id+1,id-w,id+w})if(n>=0&&n<cells.length&&Math.abs(n%w-id%w)+Math.abs(n/w-id/w)==1&&cells[n]==1&&!seen.containsKey(n)){seen.put(n,seen.get(id)+1);q.add(n);}}return seen;}
    static void compile(JSONObject map,JSONObject options){
        double size=options.optDouble("cellSizeM",1),friction=options.optDouble("friction",.6);RampDefinition.range(size,.6,1.2,"cellSizeM");RampDefinition.range(friction,.05,1.2,"friction");int w=map.getInt("width"),h=map.getInt("height");var objects=new JSONArray();objects.put(box("floor",new double[]{0,-.15,0},new double[]{w*size,.3,h*size},0,friction));
        var cells=map.getJSONArray("cells");var open=map.getJSONArray("walkable");boolean[] done=new boolean[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int id=y*w+x;if(done[id]||open.getBoolean(cells.getInt(id)))continue;int width=1,height=1;while(x+width<w&&!done[id+width]&&!open.getBoolean(cells.getInt(id+width)))width++;outer:while(y+height<h){for(int k=0;k<width;k++)if(done[(y+height)*w+x+k]||open.getBoolean(cells.getInt((y+height)*w+x+k)))break outer;height++;}for(int yy=0;yy<height;yy++)for(int xx=0;xx<width;xx++)done[(y+yy)*w+x+xx]=true;objects.put(box("wall-"+id,new double[]{(x+(width-1)/2.0-(w-1)/2.0)*size,.55,(y+(height-1)/2.0-(h-1)/2.0)*size},new double[]{width*size,1.1,height*size},0,friction));}
        if(objects.length()>512)throw new IllegalArgumentException("Compiled collider budget512 exceeded");var path=map.getJSONArray("path");if(path.length()<2)throw new IllegalArgumentException("Playable route requires two cells");var spawn=position(map,path.getInt(0),size);objects.put(box("avatar",spawn,new double[]{.36,.36,.36},1,friction));map.put("cellSizeM",size).put("friction",friction).put("gravityMps2",9.81).put("objects",objects).put("scope",SCOPE);
        int[] binary=new int[w*h];for(int i=0;i<binary.length;i++)binary[i]=open.getBoolean(cells.getInt(i))?1:0;int reachable=flood(binary,w,h,path.getInt(0)).size();map.put("metrics",new JSONObject().put("floorCells",Arrays.stream(binary).sum()).put("reachableCells",reachable).put("pathSteps",path.length()-1).put("colliders",objects.length()).put("compiledCells",w*h).put("physicalAxes",3).put("cellSizeM",size));
    }
    static JSONObject box(String id,double[] p,double[] size,double mass,double friction){return new JSONObject().put("id",id).put("sourceId",id).put("label",id).put("position",new JSONArray(p)).put("size",new JSONArray(size)).put("rotation",new JSONArray(new int[]{0,0,0,1})).put("massKg",mass).put("friction",friction).put("restitution",0);}
    static double[] position(JSONObject m,int cell,double size){return new double[]{(cell%m.getInt("width")-(m.getInt("width")-1)/2.0)*size,.20,(cell/m.getInt("width")-(m.getInt("height")-1)/2.0)*size};}
    static JSONObject example() throws Exception {return example(0);}
    static JSONObject example(int variant) throws Exception {var image=new BufferedImage(16,16,BufferedImage.TYPE_INT_RGB);for(int y=0;y<16;y++)for(int x=0;x<16;x++){int rgb=x==0||y==0||x==15||y==15||x==5&&y>3&&y<11?0x203449:0xd9efe5;if(x>=10&&x<=12&&y>=5&&y<=7)rgb=0xe4a364;if(variant==1){rgb=x==0||y==0||x==15||y==15||y==9&&x>3&&x<11?0x203449:0xc7e4ee;if(x>=10&&x<=12&&y>=3&&y<=4)rgb=0xe4a364;}image.setRGB(x,y,rgb);}var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);return new JSONObject().put("title","Labelled synthetic tile reference").put("pngBase64",Base64.getEncoder().encodeToString(bytes.toByteArray())).put("tilePixels",1).put("walkableColors",new JSONArray(List.of(variant==1?"#c7e4ee":"#d9efe5")));}
}
